// Show from the song (T-167): import a song generated by the test (no
// third-party audio), « Générer un show depuis le morceau » in TIMELINE,
// and get a proposed show, unsaved: the tempo of the song, a drop marker on
// the drop, cue events on the tracks. « Autre proposition » keeps the
// sections and draws other cues; « Enregistrer » writes it. The laser is
// never armed.
import { existsSync } from 'node:fs';
import path from 'node:path';
import { test, expect, useStudio, openUi, openWorkspace } from '../studio';

const studio = useStudio();

const RATE = 22_050;
const BPM = 128;
const BEAT = 60 / BPM;

/**
 * 16 quiet bars then 16 loud ones at 128 BPM: a kick on every beat (a sine
 * gliding down) and a noise hat on the off-beats, 16-bit mono WAV.
 */
function songWav(): { wav: Buffer; drop: number } {
  const beats = 128, start = 0.1;
  const seconds = start + beats * BEAT + 0.5;
  const n = Math.round(seconds * RATE);
  const x = new Float32Array(n);
  let seed = 12345;
  const noise = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x3fffffff - 1; };
  for (let k = 0; k < beats; k++) {
    const gain = k < 64 ? 0.06 : 1;
    const t0 = Math.round((start + k * BEAT) * RATE);
    for (let i = 0; i < 0.4 * RATE && t0 + i < n; i++) {
      const dt = i / RATE, tau = 0.04;
      x[t0 + i] += gain * 0.7 * Math.exp(-dt / 0.18) * Math.sin(2 * Math.PI * (45 * dt + 75 * tau * (1 - Math.exp(-dt / tau))));
    }
    const h0 = Math.round((start + (k + 0.5) * BEAT) * RATE);
    for (let i = 0; i < 0.05 * RATE && h0 + i < n; i++) x[h0 + i] += gain * 0.15 * Math.exp(-i / RATE / 0.02) * noise();
  }
  const b = Buffer.alloc(44 + 2 * n);
  b.write('RIFF', 0); b.writeUInt32LE(36 + 2 * n, 4); b.write('WAVE', 8);
  b.write('fmt ', 12); b.writeUInt32LE(16, 16); b.writeUInt16LE(1, 20); b.writeUInt16LE(1, 22);
  b.writeUInt32LE(RATE, 24); b.writeUInt32LE(RATE * 2, 28); b.writeUInt16LE(2, 32); b.writeUInt16LE(16, 34);
  b.write('data', 36); b.writeUInt32LE(2 * n, 40);
  for (let i = 0; i < n; i++) b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, x[i])) * 32767), 44 + 2 * i);
  return { wav: b, drop: start + 64 * BEAT };
}

interface Job { state: string; seed: number | null; show: string | null; analysis: { bpm: number; sections: { kind: string; start_s: number }[] } | null }
interface Show { name: string; tempo_map: { bpm: number }[]; audio: { file: string } | null; markers: { at: number; name: string }[]; tracks: { name: string; events: { start: number; len: number; source: { kind: string; id: string } }[] }[] }
const job = () => studio.get<Job>('/api/timeline/autoshow');
const timeline = () => studio.get<{ state: { name: string | null; modified: boolean; playing: boolean }; show: Show | null }>('/api/timeline');

test.beforeEach(async ({ page }) => {
  await studio.post('/api/timeline/stop');
  await studio.reset();
  await openUi(page, studio);
  await openWorkspace(page, 'timeline');
});

test('generate a show from an imported song, edit-ready and unsaved, never armed', async ({ page }) => {
  test.setTimeout(120_000);
  const { wav, drop } = songWav();
  await page.locator('#tlImportFile').setInputFiles({ name: 'Morceau auto e2e.wav', mimeType: 'audio/wav', buffer: wav });
  await expect(page.locator('#tlMsg')).toContainText('importé');
  await expect(page.locator('#tlAutoSong')).toHaveValue('Morceau auto e2e.wav');
  await expect(page.locator('#tlAuto')).toBeEnabled();
  await expect(page.locator('#tlAuto')).toHaveText('Générer un show depuis le morceau');

  await page.locator('#tlAuto').click();
  await expect.poll(async () => (await job()).state, { timeout: 90_000 }).toBe('done');
  const j = await job();
  expect(j.show).toBe('Auto Morceau auto e2e');
  expect(Math.abs(j.analysis!.bpm - BPM)).toBeLessThanOrEqual(0.5);
  await expect(page.locator('#tlAutoMsg')).toContainText('proposé, non enregistré');
  await expect(page.locator('#tlAutoMsg')).toContainText(`graine ${j.seed}`);
  await expect(page.locator('#tlAutoAgain')).toBeVisible();
  await expect(page.locator('#tlAutoCancel')).toBeHidden();

  // The show: loaded, unsaved, stopped; the song's tempo; a drop marker
  // within a beat of the drop; every event a cue of the catalogue.
  const t = await timeline();
  expect(t.state.name).toBe('Auto Morceau auto e2e');
  expect(t.state.modified).toBe(true);
  expect(t.state.playing).toBe(false);
  const show = t.show!;
  expect(show.audio!.file).toBe('Morceau auto e2e.wav');
  expect(Math.abs(show.tempo_map[0].bpm - BPM)).toBeLessThanOrEqual(0.5);
  const dropMark = show.markers.find(m => m.name.startsWith('Drop'));
  expect(dropMark, JSON.stringify(show.markers)).toBeTruthy();
  expect(Math.abs(dropMark!.at - drop)).toBeLessThanOrEqual(BEAT);
  const ids = new Set((await studio.presets()).presets.map((p: { id: string }) => p.id));
  const events = show.tracks.flatMap(tr => tr.events);
  expect(events.length).toBeGreaterThan(2);
  for (const e of events) expect(ids.has(e.source.id), e.source.id).toBe(true);
  expect(existsSync(path.join(studio.dataDir, 'shows', 'Auto Morceau auto e2e.json'))).toBe(false);
  // The editor shows it, marked as modified.
  await expect(page.locator('#tlShow')).toHaveValue('Auto Morceau auto e2e');
  await expect(page.locator('#tlModified')).toContainText('non enregistré');
  await page.screenshot({ path: 'test-results/timeline-autoshow.png' });
  expect((await studio.state()).armed).toBe(false);

  // Another proposal: the unsaved show would be replaced, so it asks first.
  page.once('dialog', d => d.accept());
  await page.locator('#tlAutoAgain').click();
  await expect.poll(async () => { const k = await job(); return k.state === 'done' && k.seed !== j.seed; }, { timeout: 90_000 }).toBe(true);
  const again = (await timeline()).show!;
  expect(again.markers).toEqual(show.markers);
  expect(JSON.stringify(again.tracks)).not.toEqual(JSON.stringify(show.tracks));

  // Saved under its name.
  await page.locator('#tlSave').click();
  await expect.poll(() => existsSync(path.join(studio.dataDir, 'shows', 'Auto Morceau auto e2e.json'))).toBe(true);
  expect((await timeline()).state.modified).toBe(false);
  expect((await studio.state()).armed).toBe(false);
});

test('a missing song is refused and a running job can be cancelled', async ({ page }) => {
  test.setTimeout(120_000);
  expect(await studio.post('/api/timeline/autoshow', { file: 'absent.wav' })).toBe(404);
  const { wav } = songWav();
  await page.locator('#tlImportFile').setInputFiles({ name: 'Annule e2e.wav', mimeType: 'audio/wav', buffer: wav });
  await expect(page.locator('#tlMsg')).toContainText(/importé|ajouté au show/);
  await page.locator('#tlAutoSong').selectOption('Annule e2e.wav');
  const before = (await timeline()).state.name;
  page.once('dialog', d => d.accept());
  await page.locator('#tlAuto').click();
  // Cancelled as soon as it shows; it may also finish first on a fast machine.
  await page.locator('#tlAutoCancel').click({ timeout: 5_000 }).catch(() => {});
  await expect.poll(async () => (await job()).state, { timeout: 90_000 }).not.toBe('running');
  const end = (await job()).state;
  if (end === 'cancelled') {
    await expect(page.locator('#tlAutoMsg')).toContainText('annulée');
    expect((await timeline()).state.name).toBe(before);
  } else {
    expect(end).toBe('done');
  }
  await expect(page.locator('#tlAuto')).toBeEnabled();
  expect((await studio.state()).armed).toBe(false);
});
